"""ThermalReport: post-test analysis, plotting, and export."""

from __future__ import annotations

import dataclasses
import logging
from pathlib import Path
from typing import TYPE_CHECKING

import numpy as np

if TYPE_CHECKING:
    from extensions_common.thermal.monitor import CooldownRecord, ThermalConfig

logger = logging.getLogger(__name__)


@dataclasses.dataclass
class JointThermalSummary:
    """Per-joint thermal statistics."""

    joint: str
    min_temp_c: float
    max_temp_c: float
    mean_temp_c: float
    final_temp_c: float
    equilibrium_temp_c: float | None
    """Mean temp over the last equilibrium window, or None if never reached."""
    time_to_equilibrium_s: float | None
    """Seconds from start to equilibrium, or None."""
    peak_rate_c_per_s: float
    """Maximum absolute dT/dt observed."""


class ThermalReport:
    """Generated by ``ThermalMonitor.stop()``. Provides analysis and export."""

    def __init__(
        self,
        dof_names: tuple[str, ...],
        watched_joints: list[str],
        history: list[tuple[float, dict[str, float]]],
        cooldowns: list[CooldownRecord],
        config: ThermalConfig,
        time_to_shutoff_s: float | None = None,
        shutoff_joint: str | None = None,
    ):
        self._dof_names = dof_names
        self._watched = watched_joints
        self._history = history
        self._cooldowns = cooldowns
        self._config = config
        self._time_to_shutoff_s = time_to_shutoff_s
        self._shutoff_joint = shutoff_joint

    @property
    def duration_s(self) -> float:
        if len(self._history) < 2:
            return 0.0
        return self._history[-1][0] - self._history[0][0]

    @property
    def num_samples(self) -> int:
        return len(self._history)

    @property
    def skip_heavier(self) -> bool:
        """True if shutoff occurred before early_exit_threshold_s — signals the
        peak payload test runner to stop incrementing weight."""
        if self._time_to_shutoff_s is None:
            return False
        return self._time_to_shutoff_s < self._config.early_exit_threshold_s

    @property
    def skip_heavier_reason(self) -> str | None:
        """Human-readable reason for skip_heavier, or None."""
        if not self.skip_heavier:
            return None
        return (
            f"shutoff on {self._shutoff_joint} in {self._time_to_shutoff_s:.0f}s "
            f"< {self._config.early_exit_threshold_s:.0f}s threshold"
        )

    def summary(self) -> dict[str, JointThermalSummary]:
        """Per-joint thermal statistics for all watched joints."""
        result = {}
        for joint in self._watched:
            # Single pass to extract times and temps
            times = []
            temps = []
            for entry in self._history:
                if joint in entry[1]:
                    times.append(entry[0])
                    temps.append(entry[1][joint])
            if not temps:
                continue

            temps_arr = np.array(temps)
            times_arr = np.array(times)

            # Peak rate of change
            peak_rate = 0.0
            if len(temps_arr) > 1:
                dt = np.diff(times_arr)
                d_temp = np.diff(temps_arr)
                nonzero = dt > 0
                if nonzero.any():
                    rates = np.abs(d_temp[nonzero] / dt[nonzero])
                    peak_rate = float(rates.max())

            # Dual-window equilibrium: both short and long windows must pass
            eq_temp = None
            eq_time = None
            short_w = self._config.equilibrium_window_s
            short_th = self._config.equilibrium_threshold_c
            long_w = self._config.equilibrium_window_long_s
            long_th = self._config.equilibrium_threshold_long_c
            if len(times_arr) >= 2:
                short_ends = np.searchsorted(times_arr, times_arr + short_w, side="right")
                long_ends = np.searchsorted(times_arr, times_arr + long_w, side="right")
                for i in range(len(times_arr)):
                    # Short window check
                    js = short_ends[i]
                    if js <= i + 1:
                        continue
                    short_slice = temps_arr[i:js]
                    if (times_arr[js - 1] - times_arr[i]) < short_w * 0.8:
                        continue
                    if (short_slice.max() - short_slice.min()) > short_th:
                        continue
                    # Long window check (starts at same point)
                    jl = long_ends[i]
                    if jl <= i + 1:
                        continue
                    long_slice = temps_arr[i:jl]
                    if (times_arr[jl - 1] - times_arr[i]) < long_w * 0.8:
                        continue
                    if (long_slice.max() - long_slice.min()) > long_th:
                        continue
                    # Both windows pass
                    eq_temp = float(short_slice.mean())
                    eq_time = float(times_arr[i] - times_arr[0])
                    break

            result[joint] = JointThermalSummary(
                joint=joint,
                min_temp_c=float(temps_arr.min()),
                max_temp_c=float(temps_arr.max()),
                mean_temp_c=float(temps_arr.mean()),
                final_temp_c=float(temps_arr[-1]),
                equilibrium_temp_c=eq_temp,
                time_to_equilibrium_s=eq_time,
                peak_rate_c_per_s=peak_rate,
            )
        return result

    @property
    def has_cooldowns(self) -> bool:
        """True if any cooldown events were recorded."""
        return bool(self._cooldowns)

    def cooldown_summary(self) -> list[dict]:
        """Summary of all cooldown events."""
        results = []
        for cd in self._cooldowns:
            results.append(
                {
                    "joint": cd.joint,
                    "peak_temp_c": cd.peak_temp_c,
                    "target_temp_c": cd.target_temp_c,
                    "completed": cd.completed,
                    "time_to_cool_s": cd.time_to_cool_s,
                    "decay_tau_s": cd.decay_tau_s,
                    "num_samples": len(cd.timestamps),
                    "num_torque_warnings": len(cd.torque_warnings),
                }
            )
        return results

    # -- Plotting --

    def _extract_joint_series(self, joint: str) -> tuple[list[float], list[float]]:
        """Extract (times_minutes, temps) for a joint from history. Single pass."""
        if not self._history:
            return [], []
        t0 = self._history[0][0]
        times = []
        temps = []
        for entry in self._history:
            if joint in entry[1]:
                times.append((entry[0] - t0) / 60.0)
                temps.append(entry[1][joint])
        return times, temps

    @staticmethod
    def _save_and_close(fig, save_path: str | None, show: bool):
        """Save/show/close a matplotlib figure."""
        import matplotlib.pyplot as plt

        if save_path:
            Path(save_path).parent.mkdir(parents=True, exist_ok=True)
            fig.savefig(save_path, dpi=150, bbox_inches="tight")
            logger.info("Saved plot to %s", save_path)
        if show:
            plt.show()
        plt.close(fig)

    def plot_temp_vs_time(self, joints: list[str] | None = None, save_path: str | None = None, show: bool = False):
        """Plot temperature curves over time for specified joints."""
        import matplotlib.pyplot as plt

        joints = joints or self._watched
        if not self._history:
            logger.warning("No thermal history to plot")
            return

        fig, ax = plt.subplots(figsize=(12, 6))

        for joint in joints:
            times, temps = self._extract_joint_series(joint)
            if times:
                ax.plot(times, temps, label=joint, linewidth=1.5)

        ax.axhline(
            self._config.shutoff_temp_c,
            color="red",
            linestyle="--",
            alpha=0.7,
            label=f"Shutoff ({self._config.shutoff_temp_c}°C)",
        )
        ax.axhline(
            self._config.warning_temp_c,
            color="orange",
            linestyle="--",
            alpha=0.5,
            label=f"Warning ({self._config.warning_temp_c}°C)",
        )
        ax.set_xlabel("Time (minutes)")
        ax.set_ylabel("Temperature (°C)")
        ax.set_title("Joint Temperature vs Time")
        ax.legend(loc="upper left", fontsize=8)
        ax.grid(True, alpha=0.3)
        self._save_and_close(fig, save_path, show)

    def plot_cooldown_curves(self, save_path: str | None = None, show: bool = False):
        """Plot all cooldown decay curves."""
        import matplotlib.pyplot as plt

        if not self._cooldowns:
            logger.warning("No cooldown data to plot")
            return

        fig, ax = plt.subplots(figsize=(10, 6))

        for cd in self._cooldowns:
            if not cd.timestamps:
                continue
            t0 = cd.timestamps[0]
            times = [(t - t0) / 60.0 for t in cd.timestamps]
            ax.plot(times, cd.temperatures, label=f"{cd.joint} (peak={cd.peak_temp_c:.0f}°C)", linewidth=1.5)

            if cd.decay_tau_s is not None and len(times) > 1:
                t_fit = np.linspace(0, times[-1], 200)
                t_fit_s = t_fit * 60.0
                t_ambient = cd.target_temp_c
                fitted = t_ambient + (cd.peak_temp_c - t_ambient) * np.exp(-t_fit_s / cd.decay_tau_s)
                ax.plot(t_fit, fitted, "--", alpha=0.5, label=f"{cd.joint} fit (tau={cd.decay_tau_s:.0f}s)")

        ax.axhline(
            self._config.cooldown_target_c,
            color="blue",
            linestyle=":",
            alpha=0.5,
            label=f"Target ({self._config.cooldown_target_c}°C)",
        )
        ax.set_xlabel("Time since cooldown start (minutes)")
        ax.set_ylabel("Temperature (°C)")
        ax.set_title("Cooldown Decay Curves")
        ax.legend(fontsize=8)
        ax.grid(True, alpha=0.3)
        self._save_and_close(fig, save_path, show)

    def plot_heat_dissipation_rate(
        self, joints: list[str] | None = None, save_path: str | None = None, show: bool = False
    ):
        """Plot dT/dt over time — shows heating and cooling rates."""
        import matplotlib.pyplot as plt

        joints = joints or self._watched
        if len(self._history) < 2:
            logger.warning("Need at least 2 samples for rate plot")
            return

        fig, ax = plt.subplots(figsize=(12, 6))

        for joint in joints:
            times_min, temps = self._extract_joint_series(joint)
            if len(times_min) < 2:
                continue

            t_arr = np.array(times_min) * 60.0  # back to seconds for rate calc
            temp_arr = np.array(temps)
            dt = np.diff(t_arr)
            d_temp = np.diff(temp_arr)
            nonzero = dt > 0
            if not nonzero.any():
                continue

            rate = d_temp[nonzero] / dt[nonzero]
            t_mid = ((np.array(times_min)[:-1] + np.array(times_min)[1:]) / 2)[nonzero]
            ax.plot(t_mid, rate, label=joint, linewidth=1.0, alpha=0.8)

        ax.axhline(0, color="gray", linewidth=0.5)
        ax.set_xlabel("Time (minutes)")
        ax.set_ylabel("dT/dt (°C/s)")
        ax.set_title("Temperature Rate of Change")
        ax.legend(fontsize=8)
        ax.grid(True, alpha=0.3)
        self._save_and_close(fig, save_path, show)

    # -- Export --

    def to_json(self) -> dict:
        """Machine-readable summary for test result aggregation."""
        result = {
            "duration_s": self.duration_s,
            "num_samples": self.num_samples,
            "joints": {k: dataclasses.asdict(v) for k, v in self.summary().items()},
            "cooldowns": self.cooldown_summary(),
            "config": dataclasses.asdict(self._config),
            "skip_heavier": self.skip_heavier,
        }
        if self.skip_heavier:
            result["skip_heavier_reason"] = self.skip_heavier_reason
        if self._time_to_shutoff_s is not None:
            result["time_to_shutoff_s"] = self._time_to_shutoff_s
            result["shutoff_joint"] = self._shutoff_joint
        return result
